package com.mantou.salesdialer.contacts;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.telecom.*;import android.util.AtomicFile;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.json.*;
/** One device-side alarm. Server atomically claims UNKNOWN before the independent adapter is called. */
final class EnterpriseQueue {
 private static final Object LOCK=new Object();private static final String ACTION="com.mantou.salesdialer.ENTERPRISE_ALARM";
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"enterprise-alarm.json"));}
 private static void write(Context c,JSONObject j)throws Exception{AtomicFile f=file(c);FileOutputStream out=f.startWrite();try{out.write(j.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}
 private static JSONObject read(Context c)throws Exception{if(!file(c).getBaseFile().exists())return new JSONObject().put("schema",1).put("state","DISABLED");byte[] bytes=file(c).readFully();if(bytes.length>8192)throw new IllegalStateException("ENTERPRISE_ALARM_INVALID");JSONObject j=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(!(j.get("schema") instanceof Integer)||j.getInt("schema")!=1||!Set.of("DISABLED","READY","CONSUMING").contains(j.getString("state")))throw new IllegalStateException("ENTERPRISE_ALARM_INVALID");if(j.getString("state").equals("DISABLED")){if(j.length()!=2)throw new IllegalStateException("ENTERPRISE_ALARM_INVALID");}else if(j.length()!=12)throw new IllegalStateException("ENTERPRISE_ALARM_INVALID");return j;}
 private static PendingIntent pending(Context c,String token,int flags){return PendingIntent.getBroadcast(c,9971,new Intent(c,EnterpriseAlarmReceiver.class).setAction(ACTION).putExtra("token",token),flags|PendingIntent.FLAG_IMMUTABLE);}
 static void disable(Context c){synchronized(LOCK){try{write(c,new JSONObject().put("schema",1).put("state","DISABLED"));}catch(Exception e){throw new IllegalStateException("ENTERPRISE_STOP_WRITE_FAILED",e);}var p=pending(c,"",PendingIntent.FLAG_NO_CREATE);if(p!=null){c.getSystemService(AlarmManager.class).cancel(p);p.cancel();}}}
 private static String owner(JSONObject status)throws Exception{JSONObject a=status.getJSONObject("actor");byte[] hash=MessageDigest.getInstance("SHA-256").digest((a.getString("tenantId")+"\n"+a.getString("userId")).getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:hash)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private static String boot(Context c){try{return Integer.toString(Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT));}catch(Exception e){throw new IllegalStateException("BOOT_ID_UNKNOWN");}}
 private static long number(JSONObject j,String name)throws Exception{Object v=j.get(name);if(!(v instanceof Integer)&&!(v instanceof Long))throw new IllegalStateException("ENTERPRISE_ALARM_INVALID");return ((Number)v).longValue();}
 private static EnterpriseTimerTicket ticket(Context c,JSONObject j)throws Exception{return new EnterpriseTimerTicket(number(j,"version"),number(j,"dueBusiness"),number(j,"businessAtArm"),number(j,"phoneWallAtArm"),number(j,"elapsedAtArm"),j.getString("boot"),j.getString("token"),j.getString("owner"),j.getString("queueId"),j.getString("accountKey"),EnterpriseLivePermit.outsideWindow(c,j.getString("queueId")));}
 private static void phoneReady(Context c,String account)throws Exception{if(c.checkSelfPermission(Manifest.permission.CALL_PHONE)!=PackageManager.PERMISSION_GRANTED||c.checkSelfPermission(Manifest.permission.READ_PHONE_STATE)!=PackageManager.PERMISSION_GRANTED||c.checkSelfPermission(Manifest.permission.READ_PHONE_NUMBERS)!=PackageManager.PERMISSION_GRANTED)throw new IllegalStateException("PHONE_PERMISSION_REQUIRED");if(!PilotPhoneRuntime.selectedAccount(c).key.equals(account))throw new IllegalStateException("SALES_SIM_CHANGED");if(!PilotPhoneRuntime.idle(c))throw new IllegalStateException("DEVICE_BUSY");if(c.getSystemService(ActivityManager.class).isBackgroundRestricted())throw new IllegalStateException("BACKGROUND_RESTRICTED");}
 static JSONObject start(Context c)throws Exception{disable(c);JSONObject auth=EnterpriseSession.stored(c);try{JSONObject status=EnterpriseSession.statusAs(c,auth),q=status.optJSONObject("queue");if(q==null||!q.getString("state").equals("RUNNING"))throw new IllegalStateException("QUEUE_STOPPED");if(status.getJSONObject("metrics").getInt("pending")>0)throw new IllegalStateException("PENDING_RECONCILIATION");var account=PilotPhoneRuntime.selectedAccount(c);phoneReady(c,account.key);if(!c.getSystemService(AlarmManager.class).canScheduleExactAlarms())throw new IllegalStateException("EXACT_ALARM_REQUIRED");if(status.getString("mode").equals("LIVE"))EnterpriseLivePermit.ready(c,status,q,account.key);
   long wall=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime(),business=number(status,"businessNow"),due=number(q,"nextDueAt");String nonce=UUID.randomUUID().toString().replace("-","");var t=new EnterpriseTimerTicket(number(q,"version"),due,business,wall,elapsed,boot(c),nonce,owner(status),q.getString("id"),account.key,status.getString("mode").equals("LIVE")&&EnterpriseLivePermit.outsideWindow(c,q.getString("id")));String validity=t.status(wall,elapsed,boot(c),t.owner,t.ticket.version);if(!Set.of("EARLY_TIMER","DUE").contains(validity))throw new IllegalStateException(validity);JSONObject state=new JSONObject().put("schema",1).put("state","READY").put("token",nonce).put("owner",t.owner).put("queueId",t.queueId).put("accountKey",account.key).put("version",t.ticket.version).put("dueBusiness",due).put("businessAtArm",business).put("phoneWallAtArm",wall).put("elapsedAtArm",elapsed).put("boot",t.ticket.boot);
   synchronized(LOCK){JSONObject current=EnterpriseSession.stored(c);if(auth==null||current==null||!auth.getString("token").equals(current.getString("token")))throw new IllegalStateException("OWNER_CHANGED");write(c,state);c.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,Math.max(elapsed,t.ticket.dueElapsed),pending(c,nonce,PendingIntent.FLAG_UPDATE_CURRENT));}return new JSONObject().put("armed",true).put("mode",status.getString("mode")).put("dueInMs",Math.max(0,due-business));
  }catch(Exception e){disable(c);EnterpriseOperatorBatch.clear(c);try{EnterpriseSession.pauseRemoteAs(c,auth);}catch(Exception ignored){}throw e;}}
 private static boolean consuming(Context c,String nonce)throws Exception{synchronized(LOCK){JSONObject state=read(c);return state.getString("state").equals("CONSUMING")&&state.optString("token").equals(nonce);}}
 private static void finish(Context c,String nonce)throws Exception{synchronized(LOCK){JSONObject state=read(c);if(state.optString("token").equals(nonce))disable(c);}}
 private static void report(Context c,String code,String source,String attempt,boolean api)throws Exception{JSONObject j=new JSONObject().put("status",code).put("source",source).put("attemptId",attempt).put("apiAccepted",api).put("actualOutgoing",JSONObject.NULL).put("actualConnected",JSONObject.NULL).put("at",System.currentTimeMillis());AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"enterprise-last-execution.json"));FileOutputStream out=f.startWrite();try{out.write(j.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}
 static void fire(Context c,String nonce){JSONObject state,auth=null;String source="UNKNOWN",attempt="";boolean api=false;try{synchronized(LOCK){state=read(c);if(!state.getString("state").equals("READY")||!state.optString("token").equals(nonce))return;ticket(c,state);state.put("state","CONSUMING");write(c,state);}EnterpriseSession.deadline(SystemClock.elapsedRealtime()+7000);var t=ticket(c,state);auth=EnterpriseSession.stored(c);if(auth==null)throw new IllegalStateException("AUTH_REQUIRED");JSONObject savedActor=new JSONObject().put("actor",auth.getJSONObject("actor"));if(!t.owner.equals(owner(savedActor))){auth=null;throw new IllegalStateException("OWNER_CHANGED");}JSONObject status=EnterpriseSession.statusAs(c,auth),q=status.optJSONObject("queue");String clock=t.status(System.currentTimeMillis(),SystemClock.elapsedRealtime(),boot(c),owner(status),q==null?-1:number(q,"version"));if(!clock.equals("DUE")||q==null||!t.queueId.equals(q.getString("id")))throw new IllegalStateException(clock.equals("DUE")?"STALE_QUEUE":clock);phoneReady(c,t.accountKey);if(!consuming(c,nonce))throw new IllegalStateException("QUEUE_STOPPED");JSONObject claim=EnterpriseSession.commandAs(c,auth,new JSONObject().put("op","claim").put("queueId",t.queueId).put("expectedVersion",t.ticket.version).put("deviceId",EnterpriseSession.deviceId(c)).put("idle",true));source=claim.getString("source");attempt=claim.getJSONObject("attempt").getString("id");if(!consuming(c,nonce))throw new IllegalStateException("QUEUE_STOPPED");phoneReady(c,t.accountKey);if(!claim.getString("accountKey").equals(t.accountKey))throw new IllegalStateException("SALES_SIM_CHANGED");if(!t.status(System.currentTimeMillis(),SystemClock.elapsedRealtime(),boot(c),owner(status),t.ticket.version).equals("DUE"))throw new IllegalStateException("EXPIRED");
   synchronized(LOCK){if(!consuming(c,nonce))throw new IllegalStateException("QUEUE_STOPPED");JSONObject latestSession=EnterpriseSession.stored(c);if(latestSession==null||!auth.getString("token").equals(latestSession.getString("token")))throw new IllegalStateException("OWNER_CHANGED");
   if(source.equals("RECORDING")){if(!status.getString("mode").equals("REHEARSAL")||claim.getJSONObject("target").has("number"))throw new IllegalStateException("SOURCE_MISMATCH");report(c,"RECORDING_REQUEST",source,attempt,false);}
   else if(source.equals("ANDROID_SYSTEM")){if(!status.getString("mode").equals("LIVE"))throw new IllegalStateException("SOURCE_MISMATCH");EnterpriseLivePermit.consume(c,status,q,claim,t.accountKey);String number=claim.getJSONObject("target").getString("number");if(!number.matches("1[3-9][0-9]{9}"))throw new IllegalStateException("UNSUPPORTED_NUMBER");if((!SalesPlanModel.window(System.currentTimeMillis())&&!EnterpriseLivePermit.outsideWindow(c,q.getString("id")))||!consuming(c,nonce))throw new IllegalStateException("OUTSIDE_WINDOW");if(c.checkSelfPermission(Manifest.permission.CALL_PHONE)!=PackageManager.PERMISSION_GRANTED)throw new IllegalStateException("PHONE_PERMISSION_REQUIRED");var handle=PilotPhoneRuntime.selectedAccount(c);if(!handle.key.equals(t.accountKey)||!PilotPhoneRuntime.idle(c))throw new IllegalStateException("DEVICE_BUSY");Bundle extras=new Bundle();extras.putParcelable(TelecomManager.EXTRA_PHONE_ACCOUNT_HANDLE,handle.handle);c.getSystemService(TelecomManager.class).placeCall(Uri.fromParts("tel",number,null),extras);}
   else throw new IllegalStateException("SOURCE_MISMATCH");}EnterpriseSession.commandAs(c,auth,new JSONObject().put("op","apiReceipt").put("attemptId",attempt).put("expectedRevision",claim.getJSONObject("attempt").getLong("revision")));api=true;report(c,"API_RECEIPT_RECORDED",source,attempt,true);
  }catch(Exception e){EnterpriseOperatorBatch.clear(c);String code=e.getMessage();if(code==null||!code.matches("[A-Z_]{1,80}"))code="ENTERPRISE_EXECUTION_FAILED";try{report(c,code,source,attempt,api);}catch(Exception ignored){}try{EnterpriseSession.pauseRemoteAs(c,auth);}catch(Exception ignored){}}
  finally{try{finish(c,nonce);}catch(Exception ignored){}EnterpriseSession.clearDeadline();EnterpriseActivity.changed();}
 }
 static JSONObject diagnostic(Context c)throws Exception{synchronized(LOCK){JSONObject state=read(c);return new JSONObject().put("state",state.getString("state")).put("actualOutgoing",JSONObject.NULL).put("actualConnected",JSONObject.NULL);}}
}
